const WORLD_MAP_SHORT: string[][] = [
  ["grass","tree","grass","grass","grass","grass","rV","grass","grass","grass","grass","tree","grass","grass"],
  ["grass","grass","grass","tree","grass","grass","rV","grass","grass","tree","grass","grass","grass","grass"],
  ["grass","grass","b1","b2","grass","grass","rV","grass","grass","b1","b2","grass","grass","grass"],
  ["tree","grass","grass","grass","grass","grass","rV","grass","grass","grass","grass","grass","tree","grass"],
  ["rH","rH","rH","rH","rH","rH","rFull","rH","rH","rH","rH","rH","rH","rH"],
  ["grass","grass","grass","grass","grass","grass","rV","grass","grass","grass","grass","grass","grass","grass"],
  ["grass","grass","b3","b6","grass","grass","rV","grass","grass","b4","b5","grass","grass","grass"],
  ["grass","tree","grass","grass","grass","grass","rV","grass","grass","grass","grass","tree","grass","grass"],
  ["grass","grass","grass","grass","fn","grass","rV","grass","tree","grass","grass","grass","grass","grass"],
  ["grass","grass","tree","grass","grass","grass","grass","grass","grass","grass","tree","grass","grass","grass"],
];

// Solid tiles: buildings, trees, fountain
const SOLID_KEYS = new Set(["b1","b2","b3","b4","b5","b6","tree","fn"]);

interface WorldCell {
  tileDataKey: string;  // key into TILE_DATA (e.g., "L010")
  shortKey: string;     // short key (e.g., "g", "rH")
  solid: boolean;
  isStation: boolean;
}

function getMinimapColor(shortKey: string): string {
  if (shortKey === "rH" || shortKey === "rV" || shortKey === "rFull") return "#555";
  if (shortKey.startsWith("b")) return "#8B4513";
  if (shortKey === "tree") return "#228B22";
  if (shortKey === "fn") return "#00CED1";
  return "#4CAF50"; // green grass default
}

function buildWorldMap(): WorldCell[][] {
  const map: WorldCell[][] = [];
  for (let r = 0; r < GRID_ROWS; r++) {
    const row: WorldCell[] = [];
    for (let c = 0; c < GRID_COLS; c++) {
      const shortKey = WORLD_MAP_SHORT[r][c];
      const tileDataKey = TILE_KEY_MAP[shortKey] || "L010";
      row.push({
        tileDataKey,
        shortKey,
        solid: SOLID_KEYS.has(shortKey),
        isStation: false,
      });
    }
    map.push(row);
  }
  return map;
}

